script:
app.beginUndoGroup("Glitch Bad TV");
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) throw new Error("Open a composition first.");
if (comp.selectedLayers.length < 1) throw new Error("Select at least one layer.");
for (var i = 0; i < comp.selectedLayers.length; i++) {
  var layer = comp.selectedLayers[i];
  var effects = layer.property("ADBE Effect Parade");
  var wave = effects.addProperty("ADBE Wave Warp");
  wave.property("ADBE Wave Warp-0001").setValue(1);
  wave.property("ADBE Wave Warp-0002").setValue(6);
  wave.property("ADBE Wave Warp-0003").setValue(120);
  wave.property("ADBE Wave Warp-0004").setValue(90);
  wave.property("ADBE Wave Warp-0007").expression = "time * 180";
  var signal = effects.addProperty("ADBE Slider Control");
  signal.name = "Signal Noise";
  signal.property(1).setValue(15);
  var noise = effects.addProperty("ADBE Noise HLS2");
  noise.property("ADBE Noise HLS2-0001").setValue(3);
  noise.property("ADBE Noise HLS2-0003").expression = 'effect("Signal Noise")("Slider")';
  noise.property("ADBE Noise HLS2-0004").setValue(5);
  noise.property("ADBE Noise HLS2-0005").setValue(1.5);
  noise.property("ADBE Noise HLS2-0006").expression = "time * 48";
  var blinds = effects.addProperty("ADBE Venetian Blinds");
  blinds.property("ADBE Venetian Blinds-0001").setValue(15);
  blinds.property("ADBE Venetian Blinds-0002").setValue(0);
  blinds.property("ADBE Venetian Blinds-0003").setValue(4);
  blinds.property("ADBE Venetian Blinds-0004").setValue(0);
}
app.endUndoGroup();
